<?php $title='Pages';require __DIR__.'/_layout.php';if(!can_manage('pages'))exit('Forbidden');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$vals=[];foreach(['title', 'slug', 'content', 'seo_title', 'seo_description'] as $f)$vals[] = trim($_POST[$f]??'');$cols=implode(',',['title', 'slug', 'content', 'seo_title', 'seo_description']);$qs=implode(',',array_fill(0,count($vals),'?'));$st=db()->prepare("INSERT INTO pages ($cols) VALUES ($qs)");$st->execute($vals);flash('success','Saved.');redirect('pages.php');}if(isset($_GET['delete'])){db()->prepare("DELETE FROM pages WHERE id=?")->execute([(int)$_GET['delete']]);redirect('pages.php');}$rows=db()->query("SELECT * FROM pages ORDER BY id DESC")->fetchAll();?><div class="toolbar"><h1>Pages</h1></div><form class="form" method="post"><?=csrf_field()?><label>Title</label><input name="title" required><label>Slug</label><input name="slug" required><label>Content</label><textarea name="content" rows="2" required></textarea><label>Seo Title</label><input name="seo_title" required><label>Seo Description</label><textarea name="seo_description" rows="2" required></textarea><button>Save</button></form><section class="section"><table class="table"><tr><th>ID</th><th>title</th><th>slug</th><th>content</th><th>seo_title</th><th>seo_description</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e(mb_strimwidth($r["title"]??"",0,80,"…"))?></td><td><?=e(mb_strimwidth($r["slug"]??"",0,80,"…"))?></td><td><?=e(mb_strimwidth($r["content"]??"",0,80,"…"))?></td><td><?=e(mb_strimwidth($r["seo_title"]??"",0,80,"…"))?></td><td><?=e(mb_strimwidth($r["seo_description"]??"",0,80,"…"))?></td><td><a data-confirm="Delete?" href="pages.php?delete=<?=$r['id']?>">Delete</a></td></tr><?php endforeach;?></table></section><?php require __DIR__.'/_footer.php';?>